import base64, io
from pathlib import Path
from PIL import Image

DATA = """ c46qG7pALrPxGXbVkjgbtByjuCQ1bw0tj6txYniq6uOOk5M+rtAls kS3W3Fr09PA57ppC15LAWt+7oNVoYZD4Rjr5y4ERtv l4g2ssKJ73w2jcdpGLW+83+y0cJxSGihqJn9aolIDW8AAN5XDHCzLdrPus43VUjqrM+mLjG/I95PlW4BZI2VVXDZRbNltAlkmpJNH7VxuSSDvJ3paeWkjkzR52O+84pbe91dmzcSpnxvEzm6P3kG4uq7h akbf7TyR6lpVmIuqm+DMijNxq7gO1Zc7w5wazyGDKO3tV496kpHRStoYcFoYa4SHMMwDOah oY6QUuJVMMXzTWh rNoLncsmrxCesEQlLbRNytAlkkddNHRyUrC0RyG7tNSuzTer610OC0bdhFecdYZdG9oWfj2cVETbHZCMZOSqnFap1D4G5zTGBYEt1A5XRBitaDEIw5rmjdmbe y5Z427TKeyL7XvpcLpWSNBkdLdrHi+nc rMp jqsRmZOyPJT NzA21J7exYElXPLUNnkfme03F9wTm11Q2rdUtfaR3laaH0LjeDLz79zTTk8GqmRt cYHT7Q BpiYQCO RRJUtb iwp4KaFrRKA SW6kqi/FKl743XYBG7M1rW2F1XNR Iag1Ga0mbNcc1ceG+5pt1L3VeKPj2ELo4Dmc52lxb iUTsp5cPbLIyF5EoF4GW04jtWacXqjNtbsBIsQGaO7+aa/FKpzWt zgBrs zcrQLFYnDn217DRr9nLRzOpWU74mW3NyvjWEVbqMSqKiIxuLGt cbu yNtm71UXfhwuE1QJW7x3pErd47 12V6BJ9Uf+mf cvPl6FJ9Vf+mf cvPUAhCEApJjdsXYxRqSbyYvMQR """
img = Image.open(io.BytesIO(base64.b64decode(DATA))).convert("RGB")

xs = [(0, 414), (420, 833), (839, 1253), (1259, 1672)]
ys = [(0, 518), (524, 941)]
outdir = Path("carousels/2026-10-07")
outdir.mkdir(parents=True, exist_ok=True)

idx = 1
for y0, y1 in ys:
    for x0, x1 in xs:
        crop = img.crop((x0, y0, x1, y1))
        cw, ch = crop.size
        ratio = 4 / 5
        if cw / ch > ratio:
            canvas_h = round(cw / ratio)
            canvas = Image.new("RGB", (cw, canvas_h), (0, 0, 0))
            canvas.paste(crop, (0, (canvas_h - ch) // 2))
        else:
            canvas_w = round(ch * ratio)
            canvas = Image.new("RGB", (canvas_w, ch), (0, 0, 0))
            canvas.paste(crop, ((canvas_w - cw) // 2, 0))
        canvas = canvas.resize((1080, 1350), Image.Resampling.LANCZOS)
        canvas.save(outdir / f"fitofertas_carrossel_{idx:02d}.jpg", "JPEG", quality=94, optimize=True)
        idx += 1
